class Solution:
    def numSquares(self, n: int) -> int:
        dp = [0] + [float("inf")] * n       # dp[i]：和为 i 最少几个平方数
        for i in range(1, n + 1):
            j = 1
            while j * j <= i:
                dp[i] = min(dp[i], dp[i - j * j] + 1)   # 最后一个数取 j²
                j += 1
        return dp[n]

