class Solution:
    def numSquares(self, n: int) -> int:
        dp = [0] * (n + 1)
        for i in range(1, n + 1):
            dp[i] = 1 + min(dp[i - j * j] for j in range(1, isqrt(i) + 1))
        return dp[n]

from math import isqrt

class Solution:
    def numSquares(self, n: int) -> int:
        is_sq = lambda x: isqrt(x) ** 2 == x
        if is_sq(n):
            return 1
        while n % 4 == 0:
            n //= 4
        if n % 8 == 7:
            return 4
        if any(is_sq(n - i * i) for i in range(1, isqrt(n) + 1)):
            return 2
        return 3

